local context = require "wa.context"
local events = require "wa.events"
local emotions = require "wa.emotions"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local JOB_WAN = variables.character_integer "job_wan"

return function()
  local npc = context:get_instance()
  events.on("click", function(player, conversation)
    R.run(function()
      if (JOB_WAN:get(player) == 6) then
        conversation:say("[Dancer Kim]", "Exercising together is good but if we compete for it, I think we'll get a better effect!")
        conversation:wait_for_next()
        conversation:say("[Dancer Kim]", "From now on, let's compete to see who defeats the Yellow Novus first!")
        conversation:wait_for_next()
        conversation:say("[Dancer Kim]", "You need to defeat 50 Yellow Novus!", "Are you ready?")
        conversation:wait_for_next()
        if (conversation:choose("No.", "Yes.") == 1) then
          conversation:say("[Dancer Kim]", "Hurry up before I lose interest!")
          do return end
        end
        conversation:say("[Dancer Kim]", "Good! Then ready, set~~", "Go!")
        JOB_WAN:set(player, 7)
        player:change_quest(2220, 2221)
        do return end
      elseif (JOB_WAN:get(player) == 7) then
        if ((R.checkquest(player, 2221, 1, true) == 0) or (R.checkquest(player, 2221, 1, true) == 1)) then
          if (R.checkquest(player, 2221, 2, true) == 2) then
            conversation:say("[Dancer Kim]", "Whew!", "Looks like I've lost!")
            conversation:wait_for_next()
            conversation:say("[Dancer Kim]", "This feeling reminds me of the past where I've crossed the borders of many continents.")
            conversation:wait_for_next()
            conversation:say("[Dancer Kim]", "Ah! Look at this!", "I'm getting slimmer, can you see it?")
            conversation:wait_for_next()
            conversation:say("[Dancer Kim]", "I feel that my body is full of power.", "I suddenly want to see my good partner Guitar Song.", "I want to start dancing again.")
            conversation:wait_for_next()
            conversation:choose("How about dancing in Lutie?")
            npc:show_emotion(emotions.surprise)
            conversation:say("[Dancer Kim]", "Ah! Christmas Village! Yes! Yes!", "My dream to dance in Lutie will finally come true.")
            conversation:wait_for_next()
            conversation:say("[Dancer Kim]", "I want to dance and jump all day to bring people happiness!", "So I will go to Lutie.")
            conversation:wait_for_next()
            conversation:say("[Dancer Kim]", "Ah, do me a favor, please.", "Can you bring Guitar Song to Lutie?", "Say that his partner is waiting for him.")
            conversation:wait_for_next()
            conversation:choose("No problem!")
            conversation:say("[Dancer Kim]", "You're a good person. I'm really happy that I met you.", "Thank god for sending such a stubborn person to me!")
            JOB_WAN:set(player, 8)
            player:change_quest(2221, 2222)
            do return end
          else
            conversation:say("[Dancer Kim]", "Does it look easy to you?", "But I'm sure I have a better chance to win.")
            do return end
          end
        elseif (R.checkquest(player, 2221, 1, true) == 2) then
          conversation:say("[Dancer Kim]", "Oh, you came back to me.", "I'm so tired. I don't give up halfway. It's a good exercise for me. I will have to give up Nollio to another Wanderer, it's all over....")
          conversation:wait_for_next()
          conversation:say("- Dancer Kim dropped down by grief and fatigue -")
          JOB_WAN:set(player, 6)
          player:change_quest(2221, 2220)
          do return end
        else
          conversation:say("[Dancer Kim]", "Huh...?")
          JOB_WAN:set(player, 6)
          do return end
        end
      elseif (JOB_WAN:get(player) == 8) then
        conversation:say("[Dancer Kim]", "Please tell Song, I will be waiting for him at the Christmas tree.")
        do return end
      end
      conversation:say("[Dancer Kim]", "Hunting Novus is the best exercise, I think.")
      do return end
    end)
  end)
end
